/** Media up to this size is sent inline; larger media goes through a Puter file. */
export const MAX_INLINE_MEDIA_BYTES: number;
export function createMediaStager(puter: import("../../../index.js").Puter): {
    stage: <T>(value: T, { inlineOnFailure }?: {
        inlineOnFailure?: boolean;
    }) => Promise<T | string>;
    stageImage: <T>(value: T) => Promise<string | T>;
    cleanup: () => Promise<void>;
};
